def _with_digest(plan):
    canonical = json.dumps(plan, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    plan["plan_sha256"] = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    return plan


def previous_manual_plan(dof):
    """Historical full-coverage plan, accepted only when reading an old report."""
    if type(dof) is not int or dof not in (24, 28):
        raise ValueError("人工检查仅支持24或28关节")
    return _with_digest(copy.deepcopy(_PROFILES[str(dof)]))


def excluded_waist_manual_plan(dof):
    """Previous plan with waist roll omitted; retained for historical reports."""
    if type(dof) is not int or dof not in (24, 28):
        raise ValueError("人工检查仅支持24或28关节")
    plan = copy.deepcopy(_PROFILES[str(dof)])
    plan["outcomes"] = [row for row in plan["outcomes"] if row["joint"] != "waist_roll_joint"]
    plan.pop("selected_one_endpoint_per_joint")
    plan["selected_one_endpoint_per_checked_joint"] = True
    plan["excluded_joints"] = [{"joint": "waist_roll_joint", "reason": "现场要求：腰部侧摆使用限位钉标定，本轮不检查"}]
    return _with_digest(plan)


def legacy_pin_manual_plan(dof):
    if type(dof) is not int or dof not in (24, 28):
        raise ValueError("人工检查仅支持24或28关节")
    plan = copy.deepcopy(_PROFILES[str(dof)])
    plan.pop("selected_one_endpoint_per_joint")
    plan["one_reference_per_checked_joint"] = True
    row = next(item for item in plan["outcomes"] if item["joint"] == "waist_roll_joint")
    row.update(direction="center", requested_rad=0.0, reference_rad=0.0,
               zero_direction=None, zero_pose_deg=0.0, zero_reference_error_deg=None,
               zero_source="operator_reported_pin_homing", check_side_basis="pin_zero",
               check_mode="pin_zero", tolerance_deg=0.5, pin_hold_s=5.0, pin_confirm_required=True)
    return _with_digest(plan)


def builtin_manual_plan(dof):
    plan = legacy_pin_manual_plan(dof)
    plan.pop("plan_sha256")
    for row in plan["outcomes"]:
        if row["joint"] == "waist_roll_joint":
            row["tolerance_deg"] = 2.0
        elif row["joint"] in {"left_hip_pitch_joint", "right_hip_pitch_joint"}:
            row.update(direction="center", requested_rad=0.0, reference_rad=0.0,
                       check_side_basis="zero_pose_check", check_mode="center_zero",
                       tolerance_deg=2.0, pin_hold_s=5.0, pin_confirm_required=False)
    return _with_digest(plan)


def validate_manual_plan(plan, dof):
    expected = builtin_manual_plan(dof)
    if not isinstance(plan, dict):
        raise ValueError("人工检查计划须为对象")
    try:
        json.dumps(plan, allow_nan=False)
    except (ValueError, TypeError, RecursionError) as error:
        raise ValueError("人工检查计划须为有限JSON") from error
    if type(plan.get("dof")) is not int or plan != expected:
        raise ValueError("人工检查的标零侧、对侧参考或配置摘要与本版本不符")
    return copy.deepcopy(expected)
